import type { ReactNode } from 'react';
import { cx } from '@/lib/cx';
import './description-list.css';

/**
 * B28 · DescriptionList — the record readout: what a Drawer or a detail
 * page shows when the answer is a set of labelled facts, not a table.
 * Terms speak mono uppercase like every other 76° label; values carry
 * the information.
 */
export interface DescriptionRow {
  term: string;
  children: ReactNode;
  /** id renders the value in mono · num right-aligns it and goes tabular. */
  kind?: 'text' | 'id' | 'num';
}

export interface DescriptionListProps {
  rows: DescriptionRow[];
  /** columns (default) pairs term and value side by side; stacked puts the
      value under its term — the 320px floor falls back to stacked on its own. */
  layout?: 'columns' | 'stacked';
  className?: string;
}

export function DescriptionList({ rows, layout = 'columns', className }: DescriptionListProps) {
  return (
    <dl className={cx('sv-dl', layout === 'stacked' && 'sv-dl--stacked', className)}>
      {rows.map((row) => (
        <div className="sv-dl__row" key={row.term}>
          <dt className="sv-dl__term sv-mono">{row.term}</dt>
          <dd
            className={cx(
              'sv-dl__value',
              row.kind === 'id' && 'sv-dl__value--id sv-mono',
              row.kind === 'num' && 'sv-dl__value--num sv-num',
            )}
          >
            {row.children}
          </dd>
        </div>
      ))}
    </dl>
  );
}

/* B28 · DescriptionList — labelled facts on hairlines. */

@layer sv-components {
  .sv-dl__row {
    display: grid;
    grid-template-columns: minmax(110px, 168px) 1fr;
    gap: var(--sv-s4);
    align-items: baseline;
    /* 18px horizontal, exactly B7's cell inset. B28 says the value `kind`
       inherits the table's type discipline; it inherits the table's INSET for
       the same reason. The hairline still runs edge to edge — a `<tr>` border
       does too — but the type never touches the paper's corner, which is what
       rule 18 exists to prevent and what this row was quietly doing. */
    padding: 9px 18px;
    border-bottom: 1px solid var(--sv-line);
  }

  .sv-dl__row:last-child {
    border-bottom: 0;
  }

  .sv-dl__term {
    font-size: 9.5px;
    letter-spacing: 0.13em;
    text-transform: uppercase;
    color: var(--sv-ink-soft);
  }

  .sv-dl__value {
    font-size: 13px;
    font-weight: 500;
    color: var(--sv-ink);
  }

  .sv-dl__value--id {
    font-size: 11px;
    color: var(--sv-ink-soft);
  }

  .sv-dl__value--num {
    font-weight: 600;
    text-align: right;
  }

  .sv-dl--stacked .sv-dl__row {
    grid-template-columns: 1fr;
    gap: 2px;
  }

  .sv-dl--stacked .sv-dl__value--num {
    text-align: left;
  }

  /* C7 · the 320px floor: two columns become one rather than crushing the
     value into a two-character gutter. */
  @media (max-width: 520px) {
    .sv-dl__row {
      grid-template-columns: 1fr;
      gap: 2px;
    }

    .sv-dl__value--num {
      text-align: left;
    }
  }
}
